--[=[
	@class WuKongTimer

	本类为悟空时间控制器, 用于控制游戏时间流逝.

	客户端和服务端均可调用


	```lua
	require(game.ReplicatedStorage.Packages.WuKongTimer)
	```

]=]

local rs = game:GetService("ReplicatedStorage")
require(rs.WuKong.c2l)

local WuKongTimer = {}

local c2lTimer = _G.wdm.WuKong.Core.WuKongTimer

--- 设置时间戳提供者 , 如果参数为空, 使用标准时间
function WuKongTimer.SetTimeStampProvider(handler: () -> number?): number
	c2lTimer.TimeStampProvider = handler
end

--- 获取时间戳提供者
function WuKongTimer.GetTimeStampProvider(): () -> number?
	return c2lTimer.TimeStampProvider
end

--- 获取当前时间戳
function WuKongTimer.GetTimeStamp(): number
	return c2lTimer.GetTimeStamp()
end

--- 获取当前 DateTime
function WuKongTimer.GetDateTime(): any
	local timestamp = c2lTimer.GetTimeStamp()
	return c2lTimer.GetDateTime(timestamp)
end

return WuKongTimer
